# -*- coding: utf-8 -*-
# Applies review-fix pairs from /tmp/opencode/pairs_*.json to /work/deliverable.
# All-or-nothing: verify every old string (exactly once, unless multi:true)
# BEFORE writing anything. Idempotent: if old is gone and new is present -> skip.
import json, glob, sys

FIXES = []
for f in sorted(glob.glob("/tmp/opencode/pairs_*.json")):
    FIXES.extend(json.load(open(f, encoding="utf-8")))

files = {}
fails = []
applied = skipped = 0

def load(p):
    if p not in files:
        c = open(p, encoding="utf-8", newline="").read()
        files[p] = c
        print("FILE %s len=%d crlf=%d" % (p, len(c), c.count("\r\n")))
    return files[p]

for fx in FIXES:
    p, old, new = fx["path"], fx["old"], fx["new"]
    c = load(p)
    eol = "\r\n" if "\r\n" in c else "\n"
    if fx.get("mode") == "append":
        if fx["marker"] in c:
            skipped += 1; print("SKIP append already present:", p); continue
        files[p] = c + new.replace("\n", eol)
        applied += 1; print("OK  append  %s :: %s" % (p, fx["marker"])); continue
    n = c.count(old)
    if n == 0:
        if c.count(new) >= 1:
            skipped += 1; print("SKIP already applied :: %s" % old[:70])
        elif fx.get("allow_zero"):
            print("NONE (allow_zero) :: %s" % old[:70])
        else:
            fails.append((p, old, "NOT FOUND"))
        continue
    if n > 1 and not fx.get("multi"):
        fails.append((p, old, "AMBIGUOUS x%d" % n)); continue
    files[p] = c.replace(old, new.replace("\n", eol))
    applied += n
    print("OK  x%d :: %s" % (n, old[:70]))

idx = open("/work/library/INDEX.md", encoding="utf-8").read()
print("INDEX rows:", sum(1 for L in idx.splitlines() if L.startswith("| `")))

if fails:
    print("FAILURES - nothing written:")
    for p, o, why in fails:
        print("  FAIL %s %s :: %s" % (why, p, o[:150]))
    sys.exit(1)

for p, c in files.items():
    open(p, "w", encoding="utf-8", newline="").write(c)
print("ALL OK - applied %d, skipped %d, files %d" % (applied, skipped, len(files)))

